create table if not exists public.crm_quotes (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,deal_id uuid references public.crm_deals(id) on delete set null,client_id uuid references public.clients(id) on delete set null,quote_no text not null,title text not null,status text not null default 'draft' check(status in('draft','sent','accepted','rejected','expired')),subtotal numeric not null default 0,tax numeric not null default 0,total numeric generated always as (subtotal+tax) stored,currency text not null default 'IRR',valid_until date,notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(organization_id,quote_no));
create table if not exists public.crm_quote_items (id uuid primary key default gen_random_uuid(),quote_id uuid not null references public.crm_quotes(id) on delete cascade,description text not null,quantity numeric not null default 1,unit_price numeric not null default 0,total numeric generated always as (quantity*unit_price) stored,position integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(quote_id,position));
create index if not exists crm_quotes_org_idx on public.crm_quotes(organization_id,deleted_at,updated_at desc); create index if not exists crm_quote_items_quote_idx on public.crm_quote_items(quote_id,position);
alter table public.crm_quotes enable row level security; alter table public.crm_quote_items enable row level security;
create policy crm_quotes_select on public.crm_quotes for select to authenticated using(public.crm_org_accessible(organization_id) and public.user_role()<>'client');
create policy crm_quotes_insert on public.crm_quotes for insert to authenticated with check(organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker'));
create policy crm_quotes_update on public.crm_quotes for update to authenticated using(organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker')) with check(organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker'));
create policy crm_quotes_delete on public.crm_quotes for delete to authenticated using(organization_id=public.user_org_id() and public.user_role() in('owner','admin'));
create policy crm_quote_items_select on public.crm_quote_items for select to authenticated using(exists(select 1 from public.crm_quotes q where q.id=quote_id and public.crm_org_accessible(q.organization_id) and public.user_role()<>'client'));
create policy crm_quote_items_insert on public.crm_quote_items for insert to authenticated with check(exists(select 1 from public.crm_quotes q where q.id=quote_id and q.organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker')));
create policy crm_quote_items_update on public.crm_quote_items for update to authenticated using(exists(select 1 from public.crm_quotes q where q.id=quote_id and q.organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker'))) with check(exists(select 1 from public.crm_quotes q where q.id=quote_id and q.organization_id=public.user_org_id() and public.user_role() in('owner','admin','broker')));
create policy crm_quote_items_delete on public.crm_quote_items for delete to authenticated using(exists(select 1 from public.crm_quotes q where q.id=quote_id and q.organization_id=public.user_org_id() and public.user_role() in('owner','admin')));
do $$ declare t text; begin foreach t in array array['crm_quotes','crm_quote_items'] loop execute format('drop trigger if exists block_audit_guest_writes_%I on public.%I',t,t); execute format('create trigger block_audit_guest_writes_%I before insert or update or delete on public.%I for each row execute function public.block_audit_guest_writes()',t,t); execute format('drop trigger if exists audit_%I on public.%I',t,t); execute format('create trigger audit_%I after insert or update or delete on public.%I for each row execute function public.record_audit_event()',t,t); end loop; end $$;